#!ibl edition=2
[def:외부PC준비]($PC) {
  [if:len($PC)==0] { return {ok:false,status:"invalid_input",reason:"PC 이름 또는 device_id가 필요합니다"} }
  $목록 = [self:limb]{op:"list"}
  $대상 = $목록.items >> [table:filter]{where:($행)=>$행.alias==$PC or $행.device_id==$PC}
  [if:len($대상)!=1] { return {ok:false,status:"target_not_unique",reason:"대상이 없거나 중복됩니다",items:$대상} }
  $손발 = $대상[0]
  [if:get($손발,"connected",false)==false] {
    return {ok:false,status:"offline",limb:$손발.device_id,limb_name:$손발.alias,reason:"대상 PC에서 헬퍼를 실행하세요"}
  }
  $정보 = [limbs:guestpc]{op:"info",limb:$손발.device_id}
  return {ok:true,status:"ready",limb:$정보.limb,limb_name:$정보.limb_name,env:$정보.result}
}

#!ibl edition=2
[def:외부PC작업확인]($작업,$대기=0) {
  $참조 = get($작업,"task_ref",{})
  [if:get($참조,"kind","")!="guestpc" or len(get($참조,"task_id",""))==0 or len(get($작업,"limb",""))==0 or len(get($작업,"limb_name",""))==0 or $대기<0 or $대기>240] {
    return {ok:false,status:"invalid_input",task:$작업,reason:"외부PC작업실행의 반환값과 0~240초 대기가 필요합니다",settled:false,command_ok:null}
  }
  [try] {
    $관측 = [self:task]{op:"wait",ref:$참조,timeout:$대기}
    $결과 = $관측.result
    $종료 = null
    $성공 = null
    [if:$관측.state=="succeeded" and $결과!=null] {
      $종료 = get($결과,"exit",null)
      [if:$종료!=null] { $성공 = $종료==0 and get($결과,"timeout",false)==false and len(get($결과,"error",""))==0 }
    }
    return {ok:true,status:$관측.state,limb:$작업.limb,limb_name:$작업.limb_name,task_ref:$참조,
      settled:$관측.state in ["succeeded","failed","cancelled"],command_ok:$성공,exit:$종료,
      timed_out:$관측.timed_out,progress:$관측.progress,result:$결과,failure:$관측.failure}
  } [catch] {
    return {ok:false,status:"observation_failed",limb:$작업.limb,limb_name:$작업.limb_name,task_ref:$참조,
      settled:false,command_ok:null,reason:$error.message}
  }
}

#!ibl edition=2
[def:외부PC작업실행]($PC,$명령,$작업폴더,$셸="",$실행제한=1800,$대기=0,$입력="",$환경초기화=false) {
  [if:len($PC)==0 or len($명령)==0 or len($작업폴더)==0 or $실행제한<1 or $대기<0 or $대기>240] {
    return {ok:false,status:"invalid_input",reason:"PC·명령·작업폴더, 1초 이상 실행제한, 0~240초 대기가 필요합니다"}
  }
  $접수 = [limbs:guestpc]{op:"shell",limb:$PC,cmd:$명령,cwd:$작업폴더,shell:$셸,
    timeout:$실행제한,background:true,stdin:$입력,reset:$환경초기화}
  $작업 = {limb:$접수.limb,limb_name:$접수.limb_name,task_ref:$접수.task_ref}
  $확인 = [fn:외부PC작업확인]{작업:$작업,대기:$대기}
  return {ok:true,status:"accepted",limb:$작업.limb,limb_name:$작업.limb_name,task_ref:$작업.task_ref,
    cwd:$작업폴더,observation:$확인}
}

#!ibl edition=2
[def:외부PC작업마무리]($PC,$작업들,$산출물=[],$해제=false) {
  [if:len($PC)==0 or len($작업들)==0] {
    return {ok:false,status:"invalid_input",detached:false,reason:"PC와 확인할 작업 목록이 필요합니다"}
  }
  $첫작업 = $작업들[0]
  $다른대상 = $작업들 >> [table:filter]{where:($행)=>get($행,"limb","")!=get($첫작업,"limb","")}
  [if:len(get($첫작업,"limb",""))==0 or len($다른대상)>0 or ($PC!=$첫작업.limb and $PC!=$첫작업.limb_name)] {
    return {ok:false,status:"target_mismatch",detached:false,reason:"모든 작업과 마무리 대상 PC가 같아야 합니다"}
  }
  $확인들 = $작업들 >> [table:each] { [fn:외부PC작업확인]{작업:$it,대기:0} }
  $미확정 = $확인들 >> [table:filter]{where:($행)=>$행.settled==false}
  $미성공 = $확인들 >> [table:filter]{where:($행)=>$행.command_ok!=true}
  [if:len($미확정)>0] {
    return {ok:false,status:"unfinished",limb:$첫작업.limb,detached:false,items:$확인들,artifacts:$산출물,artifacts_verified:false}
  }
  $해제결과 = null
  $종료확인 = false
  [if:$해제] {
    [try] {
      $해제결과 = [limbs:guestpc]{op:"detach",limb:$첫작업.limb}
      $종료확인 = get($해제결과,"helper_exited",false)
    } [catch] { $해제결과 = {reason:$error.message} }
  }
  return {ok:len($미성공)==0 and ($해제==false or $종료확인),status:"settled",limb:$첫작업.limb,
    commands_ok:len($미성공)==0,detached:$종료확인,detach_result:$해제결과,
    items:$확인들,artifacts:$산출물,artifacts_verified:false}
}
